class NaiveRental {
  Map<String, Vehicle> vehicles = new HashMap<>();
  public List<Vehicle> search(String type) {
    List<Vehicle> out = new ArrayList<>();
    for (Vehicle v : vehicles.values())
      if (v.type.equals(type) && !v.isBooked) out.add(v);
    return out;
  }
  public void reserve(String vehicleId) {
    vehicles.get(vehicleId).isBooked = true; // no dates, no atomicity
  }
}

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;

enum VehicleType { SEDAN, SUV, HATCHBACK, VAN }
enum VehicleStatus { AVAILABLE, UNDER_MAINTENANCE, RETIRED }
enum ReservationStatus { PENDING, CONFIRMED, ACTIVE, COMPLETED, CANCELLED, EXPIRED }

class Vehicle {
  final String vehicleId; final String storeId;
  final VehicleType type; final int dailyRate;
  volatile VehicleStatus status = VehicleStatus.AVAILABLE;
  Vehicle(String vehicleId, String storeId, VehicleType type, int dailyRate) {
    this.vehicleId = vehicleId; this.storeId = storeId;
    this.type = type; this.dailyRate = dailyRate;
  }
}

class Store {
  final String storeId;
  final Map<String, Vehicle> byId = new ConcurrentHashMap<>();
  final Map<VehicleType, Set<Vehicle>> byType = new ConcurrentHashMap<>();
  Store(String storeId) { this.storeId = storeId; }
  void addVehicle(Vehicle v) {
    byId.put(v.vehicleId, v);
    byType.computeIfAbsent(v.type, k -> ConcurrentHashMap.newKeySet()).add(v);
  }
}

class Reservation {
  final String reservationId; final String vehicleId; final String userId;
  final long startDay; final long endDay; // half-open [start, end)
  volatile ReservationStatus status;
  Reservation(String rid, String vid, String uid, long s, long e) {
    this.reservationId = rid; this.vehicleId = vid; this.userId = uid;
    this.startDay = s; this.endDay = e; this.status = ReservationStatus.PENDING;
  }
  boolean overlaps(long s, long e) { return startDay < e && s < endDay; }
}

interface PriceComponent { int compute(Reservation r, Vehicle v, int base); }
class BaseRate implements PriceComponent {
  public int compute(Reservation r, Vehicle v, int base) {
    return (int)(r.endDay - r.startDay) * v.dailyRate;
  }
}
class Tax implements PriceComponent {
  public int compute(Reservation r, Vehicle v, int base) { return base * 12 / 100; }
}

interface PaymentGateway { boolean charge(String reservationId, int amount); }

class ReservationService {
  final Map<String, Store> stores = new ConcurrentHashMap<>();
  final Map<String, Reservation> reservations = new ConcurrentHashMap<>();
  // Per-vehicle confirmed intervals + locks. Only this class writes them.
  final Map<String, List<Reservation>> confirmedByVehicle = new ConcurrentHashMap<>();
  final Map<String, ReentrantLock> locks = new ConcurrentHashMap<>();
  final List<PriceComponent> pricing = List.of(new BaseRate(), new Tax());
  final PaymentGateway gateway;
  ReservationService(PaymentGateway g) { this.gateway = g; }

  private ReentrantLock lockFor(String vehicleId) {
    return locks.computeIfAbsent(vehicleId, k -> new ReentrantLock());
  }

  List<Vehicle> search(String storeId, VehicleType type, long s, long e) {
    Store st = stores.get(storeId);
    if (st == null) return List.of();
    List<Vehicle> out = new ArrayList<>();
    for (Vehicle v : st.byType.getOrDefault(type, Set.of())) {
      if (v.status != VehicleStatus.AVAILABLE) continue;
      if (isFree(v.vehicleId, s, e)) out.add(v);
    }
    return out;
  }

  private boolean isFree(String vehicleId, long s, long e) {
    for (Reservation r : confirmedByVehicle.getOrDefault(vehicleId, List.of()))
      if (r.overlaps(s, e)) return false;
    return true;
  }

  Reservation reserve(String userId, String vehicleId, long s, long e) {
    if (s >= e) throw new IllegalArgumentException("empty interval");
    ReentrantLock lock = lockFor(vehicleId);
    lock.lock();
    try {
      if (!isFree(vehicleId, s, e)) return null; // caller maps to failure
      Reservation r = new Reservation(UUID.randomUUID().toString(), vehicleId, userId, s, e);
      reservations.put(r.reservationId, r);
      // Hold is PENDING; confirmed index updated only on pay. Prevents unpaid squatting.
      return r;
    } finally { lock.unlock(); }
  }

  boolean pay(String reservationId) {
    Reservation r = reservations.get(reservationId);
    if (r == null || r.status != ReservationStatus.PENDING) return false; // idempotent guard
    ReentrantLock lock = lockFor(r.vehicleId);
    lock.lock();
    try {
      if (r.status != ReservationStatus.PENDING) return r.status == ReservationStatus.CONFIRMED;
      if (!isFree(r.vehicleId, r.startDay, r.endDay)) { r.status = ReservationStatus.EXPIRED; return false; }
      Vehicle v = findVehicle(r.vehicleId);
      int base = 0; int total = 0;
      for (PriceComponent p : pricing) { int c = p.compute(r, v, base == 0 ? total : base); if (p instanceof BaseRate) base = c; total = (p instanceof BaseRate) ? c : total + c; }
      if (!gateway.charge(reservationId, total)) return false;
      r.status = ReservationStatus.CONFIRMED;
      confirmedByVehicle.computeIfAbsent(r.vehicleId, k -> new ArrayList<>()).add(r);
      return true;
    } finally { lock.unlock(); }
  }

  private Vehicle findVehicle(String vehicleId) {
    for (Store s : stores.values()) { Vehicle v = s.byId.get(vehicleId); if (v != null) return v; }
    throw new NoSuchElementException(vehicleId);
  }
}

// Pickup, return, cancel — the state machine that interviewers probe.
class Lifecycle {
  final ReservationService svc;
  Lifecycle(ReservationService svc) { this.svc = svc; }

  boolean pickup(String reservationId) {
    Reservation r = svc.reservations.get(reservationId);
    if (r == null || r.status != ReservationStatus.CONFIRMED) return false;
    r.status = ReservationStatus.ACTIVE;
    return true;
  }

  int returnVehicle(String reservationId, long actualEndDay, int damageFine) {
    Reservation r = svc.reservations.get(reservationId);
    if (r == null || r.status != ReservationStatus.ACTIVE) throw new IllegalStateException("not active");
    Vehicle v = svc.findVehicle(r.vehicleId);
    long billedDays = Math.max(r.endDay - r.startDay, actualEndDay - r.startDay);
    // Late days billed at 1.5x: WHY — lateness destroys the next reservation, price it punitively.
    long lateDays = Math.max(0, actualEndDay - r.endDay);
    int total = (int)(billedDays * v.dailyRate + lateDays * v.dailyRate / 2 + damageFine);
    total += total * 12 / 100; // tax computed once on final, not per component
    r.status = ReservationStatus.COMPLETED;
    return total;
  }

  boolean cancel(String reservationId, long today) {
    Reservation r = svc.reservations.get(reservationId);
    if (r == null) return false;
    if (r.status == ReservationStatus.PENDING) { r.status = ReservationStatus.CANCELLED; return true; }
    if (r.status == ReservationStatus.CONFIRMED && today < r.startDay) {
      r.status = ReservationStatus.CANCELLED;
      svc.confirmedByVehicle.getOrDefault(r.vehicleId, new ArrayList<>()).remove(r);
      return true;
    }
    return false; // active or already started: no silent cancel, needs agent override
  }
}

def is_free(existing: list[tuple[int, int]], s: int, e: int) -> bool:
    """Half-open overlap: [s,e). Adjacent bookings (e == s) do NOT overlap.
    WHY half-open: it makes back-to-back bookings trivially correct."""
    assert s < e, "empty interval"
    return all(es >= e or s >= ee for es, ee in existing)

// Pattern to recite: lock per vehicle, recheck, then mutate. Never reverse the order.
boolean paySafe(String reservationId) {
  Reservation r = reservations.get(reservationId);
  if (r == null) return false;
  ReentrantLock lock = locks.computeIfAbsent(r.vehicleId, k -> new ReentrantLock());
  lock.lock();
  try {
    if (r.status == ReservationStatus.CONFIRMED) return true;  // retry safe
    if (r.status != ReservationStatus.PENDING) return false;   // cancelled or expired
    if (!isFree(r.vehicleId, r.startDay, r.endDay)) {
      r.status = ReservationStatus.EXPIRED;
      return false;
    }
    // charge outside lock in production with pending-charge record; simplified here
    return pay(reservationId);
  } finally { lock.unlock(); }
}
